"""Normalize checkpointed continuity metadata; notes remain model reports."""

import re
from collections.abc import Sequence

from langgraph.channels import BinaryOperatorAggregate

MAX_NOTES = 8
MAX_NOTE_CHARS = 750
MAX_NOTE_SOURCES = 4
NOTE_KEY_PATTERN = re.compile(r"[a-zA-Z0-9_-]{1,40}")
SOURCE_ID_PATTERN = re.compile(r"r[a-f0-9]{32}")
BATCH_ID_PATTERN = re.compile(r"[a-f0-9]{64}")


def normalize_task_history(value: object) -> dict:
    """Bound and validate persisted history before any reader uses it.

    Keep valid references for diagnostics, but mark malformed history unavailable.
    Scope authorization and physical source availability remain the archive's job.
    """
    if value is None or (isinstance(value, dict) and not value):
        return {}
    if not isinstance(value, dict):
        return {"batches": [], "omitted_records": 0, "status": "unavailable"}
    invalid = False
    scope = value.get("scope")
    if scope is not None and (not isinstance(scope, str) or not scope):
        scope, invalid = None, True
    batches = value.get("batches", [])
    if not isinstance(batches, list):
        batches, invalid = [], True
    valid_batches = [batch for batch in batches[-64:] if isinstance(batch, str) and BATCH_ID_PATTERN.fullmatch(batch)]
    if len(valid_batches) != len(batches):
        invalid = True
    if valid_batches and scope is None:
        valid_batches, invalid = [], True
    omitted = value.get("omitted_records", 0)
    if type(omitted) is not int or omitted < 0:
        omitted, invalid = 0, True
    status = value.get("status", "available")
    if status not in ("available", "unavailable"):
        invalid = True
    return {
        **({"scope": scope} if scope is not None else {}),
        "batches": list(dict.fromkeys(valid_batches)),
        "omitted_records": omitted,
        "status": "unavailable" if invalid else status,
    }


def normalize_task_notes(value: object) -> dict:
    """Drop malformed entries and canonicalize untrusted notes without endorsing them.

    Used before external checkpoint writes and again when reading stored state:
    Overwrite and direct integrations can bypass the reducer. Source IDs are
    syntax-checked here; only the task_note tool checks their availability.
    """
    if not isinstance(value, dict):
        return {}
    notes = {}
    for key, note in value.items():
        if not isinstance(key, str) or not NOTE_KEY_PATTERN.fullmatch(key) or not isinstance(note, dict):
            continue
        content = note.get("content")
        sources = note.get("source_ids", [])
        if not isinstance(content, str) or not content or len(content) > MAX_NOTE_CHARS:
            continue
        if not isinstance(sources, list) or len(sources) > MAX_NOTE_SOURCES or any(not isinstance(source, str) or not SOURCE_ID_PATTERN.fullmatch(source) for source in sources):
            continue
        notes[key] = {"content": content, "source_ids": list(sources), "authority": "model_report"}
        if len(notes) > MAX_NOTES:
            notes.pop(next(iter(notes)))
    return notes


def merge_task_notes(left: dict | None, right: dict | None) -> dict:
    merged = normalize_task_notes(left)
    for key, value in (right if isinstance(right, dict) else {}).items():
        if value is None:
            merged.pop(key, None)
        else:
            merged.update(normalize_task_notes({key: value}))
    # Tools reject new keys at capacity; also bound externally supplied state.
    return dict(list(merged.items())[-MAX_NOTES:])


class TaskNotesChannel(BinaryOperatorAggregate[dict | None]):
    """Validate every checkpoint write, including first writes and Overwrite.

    Keep the optional channel uninitialized until it receives a write so the
    disabled feature does not add a notebook to ordinary state/SSE snapshots.
    """

    def update(self, values: Sequence[dict | None]) -> bool:
        changed = super().update(values)
        if changed:
            self.value = normalize_task_notes(self.value)
        return changed

package agent

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"strings"
	"time"

	"go-micro.dev/v6/flow"
	"go-micro.dev/v6/model"
)

const (
	agentAskStep      = "ask"
	agentApprovalStep = "approval"
	agentInputStep    = "input-required"
)

func (a *agentImpl) newCheckpointRun(runID, message, parentRunID string, info model.RunInfo, existing *flow.Run) flow.Run {
	now := time.Now()
	run := flow.Run{
		ID:         runID,
		ParentID:   parentRunID,
		Flow:       a.opts.Name,
		OriginFlow: info.Flow,
		OriginStep: info.Step,
		Dispatch:   info.Dispatch,
		Trigger:    info.Trigger,
		State:      flow.State{Stage: agentAskStep, Data: []byte(message)},
		Steps:      []flow.StepRecord{{Name: agentAskStep, Status: "in_progress"}},
		Status:     "running",
		Started:    now,
		Updated:    now,
	}
	if existing != nil {
		run = *existing
		run.Status = "running"
		run.State.Stage = agentAskStep
		if len(run.Steps) == 0 {
			run.Steps = []flow.StepRecord{{Name: agentAskStep}}
		}
		run.Steps[0].Status = "in_progress"
		run.Steps[0].Error = ""
		run.Steps[0].Result = ""
	}
	return run
}

func (a *agentImpl) saveRun(ctx context.Context, run flow.Run) error {
	if a.opts.Checkpoint == nil {
		return nil
	}
	if err := a.opts.Checkpoint.Save(ctx, run); err != nil {
		return fmt.Errorf("agent %s checkpoint save: %w", a.opts.Name, err)
	}
	if info, ok := model.RunInfoFrom(ctx); ok {
		stage := run.State.Stage
		if stage == "" && len(run.Steps) > 0 {
			stage = run.Steps[0].Name
		}
		a.recordTimelineEvent(ctx, RunEvent{
			Time: time.Now(), RunID: info.RunID, ParentID: info.ParentID, Agent: info.Agent,
			Kind: "checkpoint", Name: stage, Status: run.Status,
		})
	}
	return nil
}

// Resumer is the optional capability for resuming checkpointed runs.
// Wrappers and alternative Agent implementations can implement it without
// depending on the built-in agent's concrete type.
type Resumer interface {
	Resume(context.Context, string) (*Response, error)
}

// InputResumer is the optional capability for resuming runs with human input.
type InputResumer interface {
	ResumeInput(context.Context, string, string) (*Response, error)
}

func (a *agentImpl) Resume(ctx context.Context, runID string) (*Response, error) {
	return a.resume(ctx, runID)
}

func (a *agentImpl) ResumeInput(ctx context.Context, runID, input string) (*Response, error) {
	return a.resumeInput(ctx, runID, input)
}

// Resume returns the response for a checkpointed agent run. Completed runs are
// returned from the checkpoint without calling the model or replaying tool
// calls; failed, interrupted (timeout/rate_limited), or in-progress runs
// continue from the saved input message and reuse completed tool results.
func Resume(ctx context.Context, ag Agent, runID string) (*Response, error) {
	a, ok := ag.(Resumer)
	if !ok {
		return nil, fmt.Errorf("agent resume: unsupported agent implementation %T", ag)
	}
	return a.Resume(ctx, runID)
}

func (a *agentImpl) resume(ctx context.Context, runID string) (*Response, error) {
	if a.opts.Checkpoint == nil {
		return nil, fmt.Errorf("agent %s has no checkpoint configured", a.opts.Name)
	}
	run, ok, err := a.opts.Checkpoint.Load(ctx, runID)
	if err != nil {
		return nil, err
	}
	if !ok {
		return nil, fmt.Errorf("agent run %s not found", runID)
	}
	if paused := pendingApproval(run); paused != nil {
		return nil, paused
	}
	if run.Status == "paused" {
		if run.State.Stage == agentInputStep {
			return nil, &AwaitingInputError{RunID: runID}
		}
		run.Status = "running"
		run.State.Stage = agentAskStep
	}
	if run.Status == "done" {
		var resp Response
		if err := json.Unmarshal(run.State.Data, &resp); err != nil {
			return nil, fmt.Errorf("agent run %s response decode: %w", runID, err)
		}
		return &resp, nil
	}
	if terminalAgentRunStatus(run.Status) {
		return nil, &TerminalRunError{RunID: runID, Status: run.Status}
	}
	message := string(run.State.Data)
	parentID := run.ParentID
	a.mu.Lock()
	defer a.mu.Unlock()
	if a.model == nil {
		a.setup()
	}
	return a.askLocked(ctx, run.ID, message, parentID, &run, false)
}

// ResumeInput resumes a checkpointed agent run that paused via the built-in
// request_input tool. The supplied input is appended to the original request so
// the same run can continue with durable checkpoint and completed tool history.
func ResumeInput(ctx context.Context, ag Agent, runID, input string) (*Response, error) {
	a, ok := ag.(InputResumer)
	if !ok {
		return nil, fmt.Errorf("agent resume input: unsupported agent implementation %T", ag)
	}
	return a.ResumeInput(ctx, runID, input)
}

func (a *agentImpl) resumeInput(ctx context.Context, runID, input string) (*Response, error) {
	if a.opts.Checkpoint == nil {
		return nil, fmt.Errorf("agent %s has no checkpoint configured", a.opts.Name)
	}
	run, ok, err := a.opts.Checkpoint.Load(ctx, runID)
	if err != nil {
		return nil, err
	}
	if !ok {
		return nil, fmt.Errorf("agent run %s not found", runID)
	}
	if run.Status != "paused" || run.State.Stage != agentInputStep {
		return nil, fmt.Errorf("agent run %s is not waiting for human input", runID)
	}
	var p inputPause
	if err := run.State.Scan(&p); err != nil {
		return nil, fmt.Errorf("agent run %s input state decode: %w", runID, err)
	}
	message := p.OriginalMessage
	if message == "" {
		message = string(run.State.Data)
	}
	message += "\n\nHuman input: " + input
	run.Status = "running"
	run.State.Stage = agentAskStep
	run.State.Data = []byte(message)
	a.mu.Lock()
	defer a.mu.Unlock()
	if a.model == nil {
		a.setup()
	}
	return a.askLocked(ctx, run.ID, message, run.ParentID, &run, true)
}

func (a *agentImpl) pending(ctx context.Context) ([]flow.Run, error) {
	if a.opts.Checkpoint == nil {
		return nil, nil
	}
	runs, err := a.opts.Checkpoint.List(ctx)
	if err != nil {
		return nil, err
	}
	out := runs[:0]
	for _, run := range runs {
		if run.Flow == a.opts.Name && !terminalAgentRunStatus(run.Status) {
			out = append(out, run)
		}
	}
	return out, nil
}

func terminalAgentRunStatus(status string) bool {
	switch status {
	case "done", "canceled", "expired":
		return true
	default:
		return false
	}
}

func agentRunFailureStatus(err error) string {
	switch model.ClassifyError(err) {
	case model.ErrorKindCanceled:
		return "canceled"
	case model.ErrorKindTimeout:
		return "timeout"
	case model.ErrorKindRateLimited:
		return "rate_limited"
	default:
		return "failed"
	}
}

type operationalError struct {
	err  error
	hint string
}

func (e *operationalError) Error() string {
	if e == nil {
		return ""
	}
	return e.err.Error() + "; " + e.hint
}

func (e *operationalError) Unwrap() error {
	if e == nil {
		return nil
	}
	return e.err
}

func agentRunFailureAttempts(err error) int {
	var retryErr *model.RetryError
	if err != nil && errors.As(err, &retryErr) && retryErr.Attempts > 0 {
		return retryErr.Attempts
	}
	return 1
}

func agentOperationalError(err error) error {
	if err == nil {
		return nil
	}
	switch model.ClassifyError(err) {
	case model.ErrorKindCanceled:
		return &operationalError{err: err, hint: "agent run canceled; inspect run history with `micro inspect agent <name> --status canceled` or see docs/guides/debugging-agents.md"}
	case model.ErrorKindTimeout:
		return &operationalError{err: err, hint: "agent provider call timed out; inspect run history with `micro inspect agent <name> --status timeout`, then adjust AgentModelCallTimeout/AgentModelRetry or see docs/guides/debugging-agents.md"}
	case model.ErrorKindRateLimited:
		return &operationalError{err: err, hint: "agent provider was rate limited; inspect run history with `micro inspect agent <name> --status rate_limited`, check provider keys with `micro agent preflight`, or see docs/guides/debugging-agents.md"}
	case model.ErrorKindUnavailable:
		return &operationalError{err: err, hint: "agent provider appears temporarily unavailable; retry with bounded AgentModelRetry and verify provider setup with `micro agent preflight` or docs/guides/debugging-agents.md"}
	default:
		return err
	}
}

func (a *agentImpl) checkpointToolWrap(next model.ToolHandler) model.ToolHandler {
	return func(ctx context.Context, call model.ToolCall) model.ToolResult {
		run := a.currentRun
		if a.opts.Checkpoint == nil || run == nil {
			return next(ctx, call)
		}
		name := toolCheckpointName(call)
		if rec, ok := findStep(run.Steps, name); ok && rec.Status == "done" {
			return model.ToolResult{ID: call.ID, Value: rec.Result, Content: rec.Result}
		}

		idx := upsertStep(&run.Steps, flow.StepRecord{Name: name, Status: "in_progress"})
		_ = a.saveRun(ctx, *run)
		res := next(ctx, call)
		if idx < 0 || idx >= len(run.Steps) || run.Steps[idx].Name != name {
			idx = upsertStep(&run.Steps, flow.StepRecord{Name: name, Status: "in_progress"})
		}
		run.Steps[idx].Attempts++
		if res.Refused != "" {
			run.Steps[idx].Status = "failed"
			run.Steps[idx].Error = res.Content
			_ = a.saveRun(ctx, *run)
			return res
		}
		run.Steps[idx].Status = "done"
		run.Steps[idx].Result = res.Content
		run.Steps[idx].Error = ""
		_ = a.saveRun(ctx, *run)
		return res
	}
}

func toolCheckpointName(call model.ToolCall) string {
	b, _ := json.Marshal(call.Input)
	return "tool:" + call.Name + ":" + string(b)
}

func findStep(steps []flow.StepRecord, name string) (flow.StepRecord, bool) {
	for _, step := range steps {
		if step.Name == name {
			return step, true
		}
	}
	return flow.StepRecord{}, false
}

func upsertStep(steps *[]flow.StepRecord, rec flow.StepRecord) int {
	for i := range *steps {
		if (*steps)[i].Name == rec.Name {
			(*steps)[i].Status = rec.Status
			(*steps)[i].Error = rec.Error
			return i
		}
	}
	if len(*steps) == 0 || (*steps)[0].Name != agentAskStep {
		*steps = append([]flow.StepRecord{{Name: agentAskStep, Status: "in_progress"}}, (*steps)...)
	}
	*steps = append(*steps, rec)
	return len(*steps) - 1
}

func checkpointToolCalls(steps []flow.StepRecord) []model.ToolCall {
	calls := make([]model.ToolCall, 0, len(steps))
	for _, step := range steps {
		call, ok := checkpointToolCall(step)
		if !ok {
			continue
		}
		calls = append(calls, call)
	}
	return calls
}

func checkpointToolCall(step flow.StepRecord) (model.ToolCall, bool) {
	if step.Status != "done" || !strings.HasPrefix(step.Name, "tool:") {
		return model.ToolCall{}, false
	}
	parts := strings.SplitN(strings.TrimPrefix(step.Name, "tool:"), ":", 2)
	if len(parts) != 2 || parts[0] == "" {
		return model.ToolCall{}, false
	}
	input := map[string]any{}
	if parts[1] != "null" && parts[1] != "" {
		if err := json.Unmarshal([]byte(parts[1]), &input); err != nil {
			return model.ToolCall{}, false
		}
	}
	return model.ToolCall{Name: parts[0], Input: input, Result: step.Result}, true
}

func mergeCheckpointToolCalls(checkpointed, current []model.ToolCall) []model.ToolCall {
	if len(checkpointed) == 0 {
		return current
	}
	seen := make(map[string]struct{}, len(current))
	for _, call := range current {
		seen[toolCallKey(call.Name, call.Input)] = struct{}{}
	}
	merged := make([]model.ToolCall, 0, len(checkpointed)+len(current))
	for _, call := range checkpointed {
		if _, ok := seen[toolCallKey(call.Name, call.Input)]; ok {
			continue
		}
		merged = append(merged, call)
	}
	merged = append(merged, current...)
	return merged
}

func toolCallKey(name string, input map[string]any) string {
	b, _ := json.Marshal(input)
	return name + ":" + string(b)
}

